/**
 * The AI output disclaimer. The copy lives here, never only in an API response:
 * the API's top-level `disclaimer` string is optional (older data has none), and
 * the console must show the warning either way.
 */
export const DISCLAIMER_TITLE = "AI-generated analysis: human review required";

export const DISCLAIMER_TEXT =
  "This output was generated by AI and can be wrong. A qualified human analyst must review it before any action is taken.";

/** Compact form for tight places (verdict hero, table headers, chart cards). */
export const DISCLAIMER_BADGE_TEXT = "AI OUTPUT: HUMAN REVIEW REQUIRED";

/** The one-line bold form; identical to DISCLAIMER_MARKDOWN in the backend contract. */
const DISCLAIMER_MARKDOWN = `**${DISCLAIMER_TITLE}.** ${DISCLAIMER_TEXT}`;

/**
 * Puts the disclaimer in bold at the top and the bottom of a Markdown report, so a copied
 * or downloaded file carries the warning away from the console. Idempotent: each end is
 * checked on its own (the backend already adds both), so nothing is ever duplicated.
 */
export function withDisclaimerMarkdown(markdown: string): string {
  let body = markdown.trim();
  if (!body) return DISCLAIMER_MARKDOWN;
  if (!body.startsWith(DISCLAIMER_MARKDOWN)) {
    body = `${DISCLAIMER_MARKDOWN}\n\n---\n\n${body}`;
  }
  if (!body.endsWith(DISCLAIMER_MARKDOWN)) {
    body = `${body}\n\n---\n\n${DISCLAIMER_MARKDOWN}`;
  }
  return body;
}
